const { createServer } = require('node:http');
const { DatabaseSync } = require('node:sqlite');

const PORT = Number(process.env.PORT) || 3000;
const BASE = process.env.BASE || 'rdv.db';

const db = new DatabaseSync(BASE);
db.exec(`
  CREATE TABLE IF NOT EXISTS rendez_vous (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    telephone TEXT NOT NULL,
    date TEXT NOT NULL,
    service TEXT NOT NULL
  )
`);

const stmtInserer = db.prepare(
  'INSERT INTO rendez_vous (nom, telephone, date, service) VALUES (?, ?, ?, ?)'
);
const stmtParId = db.prepare('SELECT id, nom, telephone, date, service FROM rendez_vous WHERE id = ?');
const stmtTous = db.prepare(
  'SELECT id, nom, telephone, date, service FROM rendez_vous ORDER BY id ASC'
);

function repondre(res, statut, donnees) {
  const corps = JSON.stringify(donnees);
  res.writeHead(statut, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(corps);
}

function lireCorps(req) {
  return new Promise((resolve, reject) => {
    let brut = '';
    req.setEncoding('utf8');
    req.on('data', (morceau) => {
      brut += morceau;
    });
    req.on('end', () => resolve(brut));
    req.on('error', reject);
  });
}

const serveur = createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
  const chemin = url.pathname;

  if (chemin === '/rendez-vous' && req.method === 'POST') {
    let corps;
    try {
      const brut = await lireCorps(req);
      corps = brut ? JSON.parse(brut) : {};
    } catch {
      return repondre(res, 400, { erreur: 'Le corps de la requête doit être un JSON valide.' });
    }

    if (corps === null || typeof corps !== 'object' || Array.isArray(corps)) {
      return repondre(res, 400, { erreur: 'Le corps de la requête doit être un objet JSON.' });
    }

    const champs = ['nom', 'telephone', 'date', 'service'];
    for (const champ of champs) {
      const valeur = corps[champ];
      if (typeof valeur !== 'string' || valeur.trim() === '') {
        return repondre(res, 400, { erreur: `Le champ « ${champ} » est obligatoire.` });
      }
    }

    const info = stmtInserer.run(
      corps.nom.trim(),
      corps.telephone.trim(),
      corps.date.trim(),
      corps.service.trim()
    );

    const rdv = stmtParId.get(info.lastInsertRowid);
    return repondre(res, 201, rdv);
  }

  if (chemin === '/rendez-vous' && req.method === 'GET') {
    return repondre(res, 200, stmtTous.all());
  }

  return repondre(res, 404, { erreur: 'Adresse introuvable.' });
});

serveur.listen(PORT, () => {
  console.log(`Serveur démarré sur le port ${PORT} (base : ${BASE})`);
});
