import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync(process.env.BASE || 'rdv.db');

db.exec(`
  CREATE TABLE IF NOT EXISTS rendez_vous (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    telephone TEXT NOT NULL,
    date TEXT NOT NULL,
    service TEXT NOT NULL
  )
`);

const server = createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (req.method === 'POST' && url.pathname === '/rendez-vous') {
    let corps = '';
    req.on('data', (chunk) => { corps += chunk; });
    req.on('end', () => {
      let donnees;
      try {
        donnees = JSON.parse(corps);
      } catch {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ erreur: 'Corps de la requête JSON invalide.' }));
        return;
      }
      const { nom, telephone, date, service } = donnees ?? {};
      if (!nom || !telephone || !date || !service) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ erreur: 'Les champs nom, telephone, date et service sont tous obligatoires.' }));
        return;
      }
      const resultat = db.prepare(
        'INSERT INTO rendez_vous (nom, telephone, date, service) VALUES (?, ?, ?, ?)'
      ).run(nom, telephone, date, service);
      const rdv = { id: Number(resultat.lastInsertRowid), nom, telephone, date, service };
      res.writeHead(201, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(rdv));
    });
    return;
  }

  if (req.method === 'GET' && url.pathname === '/rendez-vous') {
    const lignes = db.prepare(
      'SELECT id, nom, telephone, date, service FROM rendez_vous ORDER BY date ASC'
    ).all();
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(lignes));
    return;
  }

  res.writeHead(404, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ erreur: 'Adresse introuvable.' }));
});

server.listen(Number(process.env.PORT) || 3000);
