    (function () {
      const boutonMenu = document.getElementById("bouton-menu");
      const menu = document.getElementById("menu-principal");
      const voile = document.getElementById("voile");
      const liensMenu = menu.querySelectorAll("a");

      function ouvrirMenu() {
        menu.classList.add("ouverte");
        voile.classList.add("visible");
        boutonMenu.setAttribute("aria-expanded", "true");
        boutonMenu.setAttribute("aria-label", "Fermer le menu");
        document.body.classList.add("menu-ouvert");
      }

      function fermerMenu() {
        menu.classList.remove("ouverte");
        voile.classList.remove("visible");
        boutonMenu.setAttribute("aria-expanded", "false");
        boutonMenu.setAttribute("aria-label", "Ouvrir le menu");
        document.body.classList.remove("menu-ouvert");
      }

      boutonMenu.addEventListener("click", function () {
        const estOuvert = boutonMenu.getAttribute("aria-expanded") === "true";
        if (estOuvert) {
          fermerMenu();
        } else {
          ouvrirMenu();
        }
      });

      liensMenu.forEach(function (lien) {
        lien.addEventListener("click", fermerMenu);
      });

      voile.addEventListener("click", fermerMenu);

      document.addEventListener("keydown", function (evenement) {
        if (evenement.key === "Escape") {
          fermerMenu();
        }
      });

      window.addEventListener("resize", function () {
        if (window.innerWidth > 780) {
          fermerMenu();
        }
      });

      const elementsAnimes = document.querySelectorAll(".reveal");

      if ("IntersectionObserver" in window) {
        const observateur = new IntersectionObserver(function (entrees) {
          entrees.forEach(function (entree) {
            if (entree.isIntersecting) {
              entree.target.classList.add("visible");
              observateur.unobserve(entree.target);
            }
          });
        }, {
          threshold: 0.12
        });

        elementsAnimes.forEach(function (element) {
          observateur.observe(element);
        });
      } else {
        elementsAnimes.forEach(function (element) {
          element.classList.add("visible");
        });
      }
    })();
  </script>
