import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import path from 'node:path';

const base = process.env.BASE || 'rdv.db';
const port = Number(process.env.PORT || 3000);

mkdirSync(path.dirname(path.resolve(base)), { recursive: true });

const db = new DatabaseSync(base);

db.prepare(`
  CREATE TABLE IF NOT EXISTS rendez_vous (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    telephone TEXT NOT NULL,
    date TEXT NOT NULL,
    service TEXT NOT NULL
  )
`).run();

const insertStmt = db.prepare(
  'INSERT INTO rendez_vous (nom, telephone, date, service) VALUES (?, ?, ?, ?)'
);
const selectAllStmt = db.prepare(
  'SELECT id, nom, telephone, date, service FROM rendez_vous ORDER BY date ASC, id ASC'
);
const selectByIdStmt = db.prepare(
  'SELECT id, nom, telephone, date, service FROM rendez_vous WHERE id = ?'
);

function sendJson(res, statusCode, data) {
  const body = JSON.stringify(data);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(body),
  });
  res.end(body);
}

async function readBody(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > 1024 * 1024) {
      throw new Error('Corps de requête trop volumineux');
    }
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}

const server = createServer(async (req, res) => {
  try {
    const pathname = new URL(req.url || '/', 'http://localhost').pathname;

    if (pathname === '/rendez-vous') {
      if (req.method === 'GET') {
        const rendezVous = selectAllStmt.all();
        sendJson(res, 200, rendezVous);
        return;
      }

      if (req.method === 'POST') {
        let data;
        try {
          const raw = await readBody(req);
          data = JSON.parse(raw);
        } catch {
          sendJson(res, 400, { erreur: 'Corps JSON invalide.' });
          return;
        }

        if (data === null || typeof data !== 'object' || Array.isArray(data)) {
          sendJson(res, 400, { erreur: 'Le corps de la requête doit être un objet JSON.' });
          return;
        }

        for (const champ of ['nom', 'telephone', 'date', 'service']) {
          const valeur = data[champ];
          if (typeof valeur !== 'string' || valeur.trim() === '') {
            sendJson(res, 400, { erreur: `Le champ « ${champ} » est obligatoire.` });
            return;
          }
        }

        const resultat = insertStmt.run(
          data.nom.trim(),
          data.telephone.trim(),
          data.date.trim(),
          data.service.trim()
        );

        const id = Number(resultat.lastInsertRowid);
        const rendezVous = selectByIdStmt.get(id);
        sendJson(res, 201, rendezVous);
        return;
      }
    }

    sendJson(res, 404, { erreur: 'Ressource introuvable.' });
  } catch (erreur) {
    console.error(erreur);
    if (!res.headersSent) {
      sendJson(res, 500, { erreur: 'Erreur interne du serveur.' });
    } else {
      res.end();
    }
  }
});

server.listen(port, () => {
  console.log(`Serveur démarré sur le port ${port} (base : ${base})`);
});
