    function fermerMenu() {
      navigation.classList.remove("ouvert");
      boutonMenu.setAttribute("aria-expanded", "false");
      boutonMenu.setAttribute("aria-label", "Ouvrir le menu");
    }

    function ouvrirMenu() {
      navigation.classList.add("ouvert");
      boutonMenu.setAttribute("aria-expanded", "true");
      boutonMenu.setAttribute("aria-label", "Fermer le menu");
    }

    boutonMenu.addEventListener("click", function () {
      const menuOuvert = boutonMenu.getAttribute("aria-expanded") === "true";
      menuOuvert ? fermerMenu() : ouvrirMenu();
    });

    liensNavigation.forEach(function (lien) {
      lien.addEventListener("click", fermerMenu);
    });

    document.addEventListener("click", function (evenement) {
      if (!entete.contains(evenement.target)) {
        fermerMenu();
      }
    });

    document.addEventListener("keydown", function (evenement) {
      if (evenement.key === "Escape" && navigation.classList.contains("ouvert")) {
        fermerMenu();
        boutonMenu.focus();
      }
    });

    window.addEventListener("resize", function () {
      if (window.innerWidth > 760) {
        fermerMenu();
      }
    });

    document.getElementById("annee").textContent = new Date().getFullYear();
  </script>
