import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';

const base = new DatabaseSync(process.env.BASE || 'rdv.db');

base.exec(`
  CREATE TABLE IF NOT EXISTS rendez_vous (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    telephone TEXT NOT NULL,
    date TEXT NOT NULL,
    service TEXT NOT NULL
  )
`);

const insererRendezVous = base.prepare(
  'INSERT INTO rendez_vous (nom, telephone, date, service) VALUES (?, ?, ?, ?)'
);
const listerRendezVous = base.prepare(
  'SELECT id, nom, telephone, date, service FROM rendez_vous ORDER BY id ASC'
);
const trouverRendezVous = base.prepare(
  'SELECT id, nom, telephone, date, service FROM rendez_vous WHERE id = ?'
);

function repondre(res, statut, donnees) {
  res.writeHead(statut, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(donnees));
}

async function lireCorpsJson(req) {
  let brut = '';
  for await (const morceau of req) {
    brut += morceau;
  }
  return brut === '' ? {} : JSON.parse(brut);
}

const serveur = createServer(async (req, res) => {
  try {
    const chemin = new URL(req.url, 'http://localhost').pathname;

    if (chemin === '/rendez-vous' && req.method === 'POST') {
      let corps;
      try {
        corps = await lireCorpsJson(req);
      } catch {
        return repondre(res, 400, {
          erreur: 'Le corps de la requête doit être un JSON valide.'
        });
      }

      for (const champ of ['nom', 'telephone', 'date', 'service']) {
        const valeur = corps?.[champ];
        if (
          valeur === undefined ||
          valeur === null ||
          (typeof valeur === 'string' && valeur.trim() === '')
        ) {
          return repondre(res, 400, {
            erreur: `Le champ « ${champ} » est obligatoire.`
          });
        }
      }

      const resultat = insererRendezVous.run(
        corps.nom,
        corps.telephone,
        corps.date,
        corps.service
      );
      const cree = trouverRendezVous.get(Number(resultat.lastInsertRowid));
      return repondre(res, 201, cree);
    }

    if (chemin === '/rendez-vous' && req.method === 'GET') {
      return repondre(res, 200, listerRendezVous.all());
    }

    return repondre(res, 404, { erreur: 'Page introuvable.' });
  } catch {
    return repondre(res, 500, { erreur: 'Erreur interne du serveur.' });
  }
});

const port = Number(process.env.PORT || 3000);
serveur.listen(port, () => {
  console.log(`Serveur démarré sur le port ${port}`);
});
