      boutonMenu.setAttribute("aria-expanded", "false");
      boutonMenu.setAttribute("aria-label", "Ouvrir le menu");
    }

    boutonMenu.addEventListener("click", () => {
      const ouvert = navigation.classList.toggle("ouverte");
      boutonMenu.setAttribute("aria-expanded", String(ouvert));
      boutonMenu.setAttribute("aria-label", ouvert ? "Fermer le menu" : "Ouvrir le menu");
    });

    navigation.addEventListener("click", (evenement) => {
      if (evenement.target.closest("a")) fermerMenu();
    });

    document.addEventListener("keydown", (evenement) => {
      if (evenement.key === "Escape" && navigation.classList.contains("ouverte")) {
        fermerMenu();
        boutonMenu.focus();
      }
    });

    window.addEventListener("resize", () => {
      if (window.innerWidth > 760) fermerMenu();
    });
