const http = require('node:http');
const { DatabaseSync } = require('node:sqlite');

const db = new DatabaseSync(process.env.BASE || 'rdv.db');

db.exec(`
  CREATE TABLE IF NOT EXISTS rendez_vous (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    telephone TEXT NOT NULL,
    date TEXT NOT NULL,
    service TEXT NOT NULL
  )
`);

const inserer = db.prepare(`
  INSERT INTO rendez_vous (nom, telephone, date, service)
  VALUES (?, ?, ?, ?)
`);
const trouver = db.prepare('SELECT * FROM rendez_vous WHERE id = ?');
const lister = db.prepare('SELECT * FROM rendez_vous ORDER BY date ASC, id ASC');

function repondre(res, code, contenu) {
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(contenu));
}

http.createServer(async (req, res) => {
  const chemin = new URL(req.url, 'http://localhost').pathname;

  try {
    if (chemin === '/rendez-vous' && req.method === 'GET') {
      return repondre(res, 200, lister.all());
    }

    if (chemin === '/rendez-vous' && req.method === 'POST') {
      let corps;
      try {
        let texte = '';
        for await (const morceau of req) texte += morceau;
        corps = JSON.parse(texte);
      } catch {
        return repondre(res, 400, { erreur: 'Corps JSON invalide.' });
      }

      for (const champ of ['nom', 'telephone', 'date', 'service']) {
        if (typeof corps?.[champ] !== 'string' || !corps[champ].trim()) {
          return repondre(res, 400, {
            erreur: `Le champ ${champ} est obligatoire.`
          });
        }
      }

      const resultat = inserer.run(
        corps.nom,
        corps.telephone,
        corps.date,
        corps.service
      );
      return repondre(res, 201, trouver.get(resultat.lastInsertRowid));
    }

    return repondre(res, 404, { erreur: 'Adresse introuvable.' });
  } catch {
    return repondre(res, 500, { erreur: 'Erreur interne du serveur.' });
  }
}).listen(process.env.PORT || 3000);
