import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';

const dbPath = process.env.BASE || 'rdv.db';
const port = process.env.PORT || 3000;

const db = new DatabaseSync(dbPath);

db.exec(`
  CREATE TABLE IF NOT EXISTS rendez_vous (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nom TEXT NOT NULL,
    telephone TEXT NOT NULL,
    date TEXT NOT NULL,
    service TEXT NOT NULL
  )
`);

const insertRdv = db.prepare(`
  INSERT INTO rendez_vous (nom, telephone, date, service)
  VALUES (?, ?, ?, ?)
`);

const selectAllRdv = db.prepare(`
  SELECT id, nom, telephone, date, service
  FROM rendez_vous
  ORDER BY date ASC, id ASC
`);

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

  if (url.pathname === '/rendez-vous') {
    if (req.method === 'GET') {
      const rdvList = selectAllRdv.all();
      res.writeHead(200, { 'Content-Type': 'application/json; charset=utf-8' });
      res.end(JSON.stringify(rdvList));
      return;
    }

    if (req.method === 'POST') {
      let body = '';
      req.on('data', (chunk) => {
        body += chunk.toString();
      });

      req.on('end', () => {
        let data;
        try {
          data = JSON.parse(body);
        } catch {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(JSON.stringify({ erreur: 'Le corps de la requête doit être un JSON valide.' }));
          return;
        }

        const { nom, telephone, date, service } = data || {};

        if (!nom || !telephone || !date || !service) {
          res.writeHead(400, { 'Content-Type': 'application/json; charset=utf-8' });
          res.end(JSON.stringify({ erreur: 'Tous les champs (nom, telephone, date, service) sont obligatoires.' }));
          return;
        }

        const result = insertRdv.run(String(nom), String(telephone), String(date), String(service));

        const nouveauRdv = {
          id: Number(result.lastInsertRowid),
          nom: String(nom),
          telephone: String(telephone),
          date: String(date),
          service: String(service)
        };

        res.writeHead(201, { 'Content-Type': 'application/json; charset=utf-8' });
        res.end(JSON.stringify(nouveauRdv));
      });
      return;
    }
  }

  res.writeHead(404, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify({ erreur: 'Ressource non trouvée.' }));
});

server.listen(port);
